pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;
    function setUp() public { c = new PhiNFT1155(); }
    function testRegression_property() public {
        address owner = address(0x1234);
        address attacker = address(0x5678);
        vm.prank(c.owner());
        c.transferOwnership(owner);
        vm.prank(attacker);
        bool ok;
        try c.acceptOwnership() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
